import { createApp, h, reactive } from 'vue';
import CLoading from '@/app/popup/components/loading.vue';

//全局loading状态(单例)
const state = reactive({
    visible: false,
    text: '处理中...'
});
let app  = null;
let root = null;

//初始化挂载节点
const initLoading = () => {
    if (app) {
        return;
    }
    root = document.createElement('div');
    root.className = 'x-loading-root';
    document.body.appendChild(root);
    app = createApp({
        render: () => h(CLoading, {visible: state.visible, text: state.text})
    });
    app.mount(root);
};

//展示loading提示 sText-提示内容
export const showLoading = (sText='处理中...') => {
    initLoading();
    state.text    = sText || '处理中...';
    state.visible = true;
};

//隐藏loading提示
export const hideLoading = () => {
    state.visible = false;
};

//异步任务自动展示loading,结束自动隐藏
export const withLoading = async (task, sText='处理中...') => {
    showLoading(sText);
    try {
        return await task();
    } finally {
        hideLoading();
    }
};

//组件内便捷调用: const { showLoading, hideLoading } = useLoading();
export const useLoading = () => {
    return { showLoading, hideLoading, withLoading };
};

export default { showLoading, hideLoading, withLoading, useLoading };
