import { APIRequest } from "@/static/js/base/request"
import { Message } from 'view-ui-plus';

//发送http业务API请求
const doRequest = async (url = '',  method = 'GET', params = {}) => {
    let result = await APIRequest(url, method, params);
    if (result && result.code == 0) {//成功的情况
        return result.data || {};
    }
    Message.error(result.message); //错误提示
    return null;
};

//加载配置信息
export const getXConfig = (level) => {
  return doRequest("/rp-x-tool", "POST", {level: level});
}

//加载工具脚本的逻辑
export const getToolScript = (uuid) => {
  return doRequest("/rp-market-exec", "POST", {uuid: uuid});
}

