<template>
    <div class="comments">
        <div class="wrap">
            <span class="search">
              <Input type="text" size="small" v-model="search.query" clearable
                placeholder="请输入导出/复制关键词过滤..."/>
            </span>
            <span class="actions" @click.stop>
              <Button @click="rnExport" type="text" size="small" icon="md-cloud-download">导出</Button>
              <Button @click="refresh" type="text" size="small" icon="md-refresh">刷新</Button>
            </span>
        </div>
        <Table stripe border :columns="columns" :data="dataStore.items">
            <template #action="{ row }">
                <Button type="success" size="small" @click="copy(row)">复制</Button>&nbsp;
                <Button type="error" size="small" @click="remove(row)">删除</Button>
            </template>
            <template #title="{ row }">
                <a target="_blank" :href="row.link">{{ row.meta.title || row.meta.desc || '--'}}</a>
            </template>
            <template #data="{ row }">
                <div class="comment-cell">
                    <div class="comment-head">
                        <span class="comment-count">
                            <Icon type="ios-chatbubbles" size="13" /> 共 {{ countAll(row) }} 条评论
                        </span>
                        <span v-if="countSub(row)" class="comment-sub">含 {{ countSub(row) }} 条回复</span>
                        <span v-if="search.query" class="comment-filter">关键词：{{ search.query }}</span>
                    </div>

                    <div v-if="commentsOf(row).length < 1" class="comment-empty">暂无评论</div>

                    <template v-else>
                        <div class="comment-list" :class="{ 'is-collapsed': !isExpanded(row) && commentsOf(row).length > topSize }">
                            <div v-for="node in flatComments(row)" :key="node.key"
                                class="comment-item" :class="{ 'is-sub': node.depth > 0 }">
                                <span class="c-avatar" :class="{ sub: node.depth > 0 }">{{ initialOf(node.item) }}</span>
                                <div class="c-body">
                                    <div class="c-meta">
                                        <strong class="c-nick">{{ nickOf(node.item) }}</strong>
                                        <span v-if="node.depth > 0" class="c-reply">回复</span>
                                        <span v-if="node.item.ip_location" class="c-loc">{{ node.item.ip_location }}</span>
                                        <span class="c-time">{{ timeOf(node.item) }}</span>
                                    </div>
                                    <p class="c-text">{{ textOf(node.item) }}</p>
                                    <div v-if="node.subTotal > subSize" class="c-more">
                                        <Button type="text" size="small" @click="toggleSub(row, node.key)">
                                            {{ node.subOpen ? '收起回复' : `展开 ${node.subTotal} 条回复` }}
                                            <Icon :type="node.subOpen ? 'ios-arrow-up' : 'ios-arrow-down'" />
                                        </Button>
                                    </div>
                                </div>
                            </div>
                            <div v-if="!isExpanded(row) && commentsOf(row).length > topSize" class="fade-mask"></div>
                        </div>

                        <div class="comment-more" v-if="commentsOf(row).length > topSize">
                            <Button type="text" size="small" @click="toggle(row)">
                                {{ isExpanded(row) ? '收起评论' : `查看全部 ${commentsOf(row).length} 条` }}
                                <Icon :type="isExpanded(row) ? 'ios-arrow-up' : 'ios-arrow-down'" />
                            </Button>
                        </div>
                    </template>
                </div>
            </template>
        </Table>
        <div style="margin-top: 8px;">
            <Page :total="dataStore.total" show-sizer :page-size="dataStore.mPagesize"
                @on-change="pageSelected" @on-page-size-change="setPagesize" />
        </div>
    </div>
</template>
<script setup>
import { onMounted, ref, reactive } from 'vue';
import utilSrv from "@/static/js/base/utils";
import { Table, Button, Page, Message, Input, Icon } from 'view-ui-plus';
import { useCommentsStore } from '@/app/store/comments';
import { showLoading, hideLoading } from '@/app/static/loading';

const topSize = 3;    // 默认展示的一级评论条数
const subSize = 2;    // 每条评论默认展示的回复条数
const maxDepth = 3;   // 最大展示层级，防止脏数据无限嵌套

const link = ref('');
const emit = defineEmits(['edit']);
const search = reactive({query:''});
const dataStore = useCommentsStore();
// 按记录 sn 单独记录展开状态：{ open, subs: {评论key: bool} }
const expandedMap = reactive({});
const currPage = ref(1);

const columns = [
    {
        title: '记录ID',
        key: 'sn',
        maxWidth: 160,
        minWidth: 80,
        resizable: true,
    },
    {
        title: '标题',
        maxWidth: 320,
        minWidth: 140,
        key: 'title',
        resizable: true,
        slot: 'title',
    },
    {
        title: '评论内容',
        key: 'data',
        minWidth: 200,
        resizable: true,
        slot: 'data',
    },
    {
        title: '更新时间',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        key: 'created_at'
    },
    {
        title: '操作',
        slot: 'action',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        align: 'center'
    }
];

//评论数组，兼容脏数据
const commentsOf = (row) => {
    const list = row && row.meta && row.meta.comments;
    return Array.isArray(list)? list:[];
};
const subsOf = (item) => {
    const list = item && item.sub_comments;
    return Array.isArray(list)? list:[];
};
const nickOf = (item) => (item && item.user && item.user.nickname) || '匿名用户';
const textOf = (item) => (item && (item.content || item.text)) || '';
const timeOf = (item) => {
    if (!item || !item.create_time) {
        return '';
    }
    return utilSrv.DateStr(item.create_time, 'Y-m-d H:i:s');
};
const initialOf = (item) => {
    const nick = nickOf(item);
    return nick.trim().charAt(0) || '#';
};

//单条记录的展开状态
const stateOf = (sn) => {
    if (!expandedMap[sn]) {
        expandedMap[sn] = { open:false, subs:{} };
    }
    if (!expandedMap[sn].subs) {
        expandedMap[sn].subs = {};
    }
    return expandedMap[sn];
};
const isExpanded = (row) => !!stateOf(row.sn).open;
const toggle = (row) => {
    const state = stateOf(row.sn);
    state.open = !state.open;
};
const toggleSub = (row, key) => {
    const state = stateOf(row.sn);
    state.subs[key] = !state.subs[key];
};
const clearExpanded = () => {
    Object.keys(expandedMap).forEach((key)=>{ delete expandedMap[key]; });
};

//遍历树形评论，cb(item, depth, key)
const walkComments = (list, cb, depth = 0, prefix = 'c') => {
    (Array.isArray(list)? list:[]).forEach((item, index)=>{
        if (!item) {
            return;
        }
        const key = item.id || `${prefix}-${index}`;
        cb(item, depth, key);
        if (subsOf(item).length && depth + 1 < maxDepth) {
            walkComments(subsOf(item), cb, depth + 1, key);
        }
    });
};

//评论总数（含回复）
const countAll = (row) => {
    let total = 0;
    walkComments(commentsOf(row), ()=>{ total++; });
    return total;
};
//回复总数（二级及以下）
const countSub = (row) => {
    let total = 0;
    walkComments(commentsOf(row), (item, depth)=>{
        if (depth > 0) {
            total++;
        }
    });
    return total;
};

//把树形评论拍平成带层级的渲染列表，按展开状态裁剪
const flatComments = (row) => {
    const state = stateOf(row.sn);
    const nodes = [];
    const walk = (list, depth, prefix, limit) => {
        const items = Array.isArray(list)? list:[];
        const visible = limit > 0? items.slice(0, limit):items;
        visible.forEach((item, index)=>{
            if (!item) {
                return;
            }
            const key = item.id || `${prefix}-${index}`;
            const subTotal = subsOf(item).length;
            const canOpen = depth + 1 < maxDepth && subTotal > 0;
            const subOpen = canOpen && !!state.subs[key];
            nodes.push({ key, depth, item, subTotal, subOpen });
            if (canOpen) {
                walk(subsOf(item), depth + 1, key, subOpen? 0:subSize);
            }
        });
    };
    walk(commentsOf(row), 0, 'c', state.open? 0:topSize);
    return nodes;
};

//关键词数组
const queryWords = () => {
    const query = (search.query || '').replaceAll('，', ',').trim();
    if (!query) {
        return null;
    }
    return query.split(',').map((w)=>w.trim()).filter((w)=>!!w);
};
const matchWords = (text, words) => {
    if (!words) {
        return true;
    }
    const str = String(text || '');
    return words.some((w)=>str.includes(w));
};

const remove = async (row) => {
    await dataStore.delete(row.sn);
};

const pageSelected = async (curPage) => {
    currPage.value = curPage;
    clearExpanded();
    await dataStore.load(curPage, link.value);
};

const setPagesize = async(pSize) => {
    dataStore.mPagesize = pSize;
    currPage.value = 1;
    clearExpanded();
    await dataStore.load(1, link.value);
}

const refresh = async () => {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    currPage.value = 1;
    clearExpanded();
    await dataStore.load(1, link.value);
}

//写入剪贴板，优先 Clipboard API，失败降级 execCommand
const writeClipboard = async (text) => {
    try {
        if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(text);
            return true;
        }
    } catch (err) {
        utilSrv.Write(utilSrv.INFO, "剪贴板不可用", err);
    }
    try {
        const area = document.createElement('textarea');
        area.value = text;
        area.setAttribute('readonly', 'readonly');
        area.style.position = 'fixed';
        area.style.top = '-1000px';
        area.style.opacity = '0';
        document.body.appendChild(area);
        area.select();
        const ok = document.execCommand('copy');
        document.body.removeChild(area);
        return ok;
    } catch (err) {
        utilSrv.Write(utilSrv.INFO, "复制失败", err);
        return false;
    }
};

//组装单条记录的评论文本，回复按缩进展示
const buildText = (row, words) => {
    const lines = [];
    let count = 0;
    walkComments(commentsOf(row), (item, depth)=>{
        if (!matchWords(textOf(item), words)) {
            return;
        }
        const time = timeOf(item);
        const indent = depth > 0? '    '.repeat(depth) + '└ ':'';
        lines.push(`${indent}${nickOf(item)}${time? '（'+time+'）':''}：${textOf(item)}`);
        count++;
    });
    const head = [`标题：${(row.meta && (row.meta.title || row.meta.desc)) || '--'}`];
    if (row.link) {
        head.push(`链接：${row.link}`);
    }
    head.push('');
    return { text: head.concat(lines).join('\n'), total: count };
};

//复制操作
const copy = async (row) => {
    if (commentsOf(row).length < 1) {
        Message.warning('该记录暂无评论内容');
        return;
    }
    const words = queryWords();
    const { text, total } = buildText(row, words);
    if (total < 1) {
        Message.warning('没有符合关键词的评论内容');
        return;
    }
    showLoading("评论复制中...");
    const ok = await writeClipboard(text);
    hideLoading();
    if (ok) {
        Message.success(`已复制 ${total} 条评论`);
    } else {
        Message.error('复制失败，请检查浏览器剪贴板权限');
    }
};

//导出操作：按评论逐行导出 CSV，含层级与回复
const rnExport = async() => {
    if (dataStore.total < 1) {
        Message.error('暂时没有数据');
        return;
    }
    const words = queryWords();
    const mPagesize = dataStore.mPagesize;
    const maxCount = 5000;
    const perPage = 500;
    const lines = [['编号','标题','链接','层级','评论ID','昵称','评论内容','评论时间','IP属地'].join(',')];
    let count = 0;
    showLoading("评论导出中...");
    try {
        dataStore.mPagesize = perPage;
        const total = Math.min(dataStore.total, maxCount);
        const pages = Math.ceil(total / perPage);
        for (let page = 1; page <= pages; page++) {
            await dataStore.load(page, link.value);
            (dataStore.items || []).forEach((row)=>{
                walkComments(commentsOf(row), (item, depth, key)=>{
                    if (!matchWords(textOf(item), words)) {
                        return;
                    }
                    const raw = [row.sn, (row.meta && (row.meta.title || row.meta.desc)) || '--',
                        row.link || '', depth + 1, key, nickOf(item), textOf(item),
                        timeOf(item), item.ip_location || ''];
                    const line = raw.map((v)=>`"${String(v ?? '').replace(/"/g, '')}"`);
                    lines.push(line.join(','));
                    count++;
                });
            });
        }
        if (count < 1) {
            Message.warning('没有符合关键词的评论内容');
            return;
        }
        const csv  = '\uFEFF' + lines.join('\n');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `评论数据_${Date.now()}.csv`;
        a.click();
        URL.revokeObjectURL(url);
        Message.success(`已导出 ${count} 条评论`);
    } catch (err) {
        utilSrv.Write(utilSrv.INFO, "评论导出失败", err);
        Message.error('导出失败，请稍后重试');
    } finally {
        dataStore.mPagesize = mPagesize;
        await dataStore.load(1, link.value);
        hideLoading();
    }
};

onMounted(async ()=>{
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.url) {//地址
       link.value = tab.url
    }
    await dataStore.load(1, link.value);
})
</script>
<style scoped>
.p-r-15 {
    padding-right: 15px;
}
.wrap {
    padding: 8px 0;
    background-color: #aaa;
    display: flex;
    justify-content: space-between;
    align-items: center; 
    .search {
        padding-left: 8px;
    }
    .actions{
        padding-right: 8px;
    }
}
.comment-cell {
    padding: 2px 0;
}
.comment-head {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 5px;
    flex-wrap: wrap;
}
.comment-count {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: #667085;
    font-size: 11px;
}
.comment-sub {
    color: #98a2b3;
    font-size: 11px;
}
.comment-filter {
    padding: 1px 6px;
    color: #b45309;
    background: #fffbeb;
    border-radius: 999px;
    font-size: 10px;
}
.comment-empty {
    padding: 8px 0;
    color: #98a2b3;
    font-size: 11px;
}
.comment-list {
    position: relative;
}
.comment-list.is-collapsed {
    padding-bottom: 10px;
}
.fade-mask {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 26px;
    background: linear-gradient(transparent, #fff);
    pointer-events: none;
}
.comment-item {
    display: flex;
    gap: 7px;
    padding: 5px 0;
    border-top: 1px dashed #eef1f6;
}
.comment-item:first-child {
    border-top: none;
}
.comment-item.is-sub {
    margin-left: 26px;
    padding: 4px 0 4px 8px;
    background: #fbfcfe;
    border-top: none;
    border-left: 2px solid #dbe3ef;
    border-radius: 0 6px 6px 0;
}
.c-avatar {
    display: inline-grid;
    width: 20px;
    height: 20px;
    flex: none;
    color: #2563eb;
    background: #eff6ff;
    border-radius: 50%;
    font-size: 10px;
    font-weight: 600;
    place-items: center;
}
.c-avatar.sub {
    width: 18px;
    height: 18px;
    color: #7c3aed;
    background: #f5f3ff;
    font-size: 9px;
}
.c-body {
    min-width: 0;
    flex: 1;
}
.c-meta {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}
.c-nick {
    overflow: hidden;
    max-width: 130px;
    color: #344054;
    font-size: 11px;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.c-reply {
    padding: 0 4px;
    color: #7c3aed;
    background: #f5f3ff;
    border-radius: 3px;
    font-size: 9px;
}
.c-loc {
    padding: 0 4px;
    color: #667085;
    background: #f4f6f9;
    border-radius: 3px;
    font-size: 9px;
}
.c-time {
    flex: none;
    color: #98a2b3;
    font-size: 10px;
}
.c-text {
    margin: 2px 0 0;
    color: #5b667a;
    font-size: 11px;
    line-height: 16px;
    word-break: break-word;
}
.c-more,
.comment-more {
    margin-top: 2px;
}
</style>
