<template>
  <section class="workspace-card feedback-card">
    <button class="feedback-entry" type="button" @click="open">
      <span class="feedback-icon"><Icon type="ios-chatbubbles" size="21" /></span>
      <span class="feedback-copy">
        <strong>意见反馈</strong>
        <small>遇到问题、有建议或想要新功能，告诉我们</small>
      </span>
      <Icon class="feedback-arrow" type="ios-arrow-forward" size="16" />
    </button>

    <Modal v-model="mState.isPop" title="意见反馈" :footer-hide="true"
      :mask-closable="false" width="480" class-name="feedback-modal">
      <div class="feedback-form">
        <div class="form-intro">
          <span class="form-intro-icon"><Icon type="ios-chatbubbles" size="20" /></span>
          <div>
            <strong>提交你的想法</strong>
            <p>我们会连同版本与当前站点信息一起记录，便于快速定位问题。</p>
          </div>
        </div>

        <div class="field-block">
          <label>反馈标题<i>*</i></label>
          <Input v-model="form.title" size="large" maxlength="60" show-word-limit
            placeholder="一句话描述，例如：小红书采集偶尔漏数据" />
        </div>

        <div class="field-block">
          <label>反馈内容<i>*</i></label>
          <Input v-model="form.content" type="textarea" :rows="5" maxlength="500" show-word-limit
            placeholder="请描述具体操作路径、出现的问题或期望的效果（至少 5 个字）" />
        </div>

        <div class="context-row">
          <span>版本 {{ mState.version }}</span>
          <span>{{ mStore.curDomain || '待识别站点' }}</span>
        </div>

        <div class="form-actions">
          <Button size="large" @click="close">取 消</Button>
          <Button type="primary" size="large" :loading="mState.loading" @click="doSubmit">
            提交反馈
          </Button>
        </div>
      </div>
    </Modal>
  </section>
</template>
<script setup>
import { reactive } from 'vue';
import { Button, Input, Modal, Icon,
  Message } from 'view-ui-plus';
import { useStore } from '@/app/store/index';
import { doFeedback } from '@/app/static/api.js';
import { xIsLogin } from "@/static/js/base/request";

const mStore = useStore();
const mState = reactive({ isPop:false,
  loading:false, version:'--' });
const form = reactive({ title:'', content:'' });

//加载版本号底子好
const loadVersion = () => {
  try {
    const manifest = chrome.runtime.getManifest();
    mState.version = manifest? `v${manifest.version}`:'--';
  } catch (err) {
    mState.version = '--';
  }
};

const curUrl = async () => {
  try {
    const [tab] = await chrome.tabs.query({ active:true, currentWindow:true });
    return (tab && tab.url)? tab.url:'';
  } catch (err) {
    return '';
  }
};

const reset = () => {
  form.title = '';
  form.content = '';
};

const open = async () => {
  const isOk = await xIsLogin();
  if (!isOk) {//为空的情况
    Message.success('请先登录!');
    return;
  }
  loadVersion();
  mState.isPop = true;
};

const close = () => {
  mState.isPop = false;
  reset();
};

const doSubmit = async () => {
  const title = (form.title || '').trim();
  const content = (form.content || '').trim();
  if (!title) {
    Message.warning('请输入反馈标题');
    return;
  }
  if (content.length < 5) {
    Message.warning('反馈内容至少 5 个字');
    return;
  }
  mState.loading = true;
  try {
    // TODO 接口对接：后端确认字段后调整 params 即可
    const params = {
      title: title,
      data: content,
      version: mState.version,
      domain: mStore.curDomain || '',
      url: await curUrl(),
    };
    const res = await doFeedback(params);
    if (!res) {
      return;//doRequest 已做错误提示
    }
    Message.success('反馈已提交，感谢你的建议');
    close();
  } catch (err) {
    Message.error('提交失败，请稍后重试');
  } finally {
    mState.loading = false;
  }
};
</script>
