const scriptMarkStart = "==UserScript==";
const scriptMarkEnd   = "==/UserScript==";
// ==UserScript==
// @name         DemoScript
// @version      0.1
// @description  try to take over the world!
// @author       Leicc
// @match        https://www.bejson.com/
// @icon         https://www.google.com/s2/favicons?sz=64&domain=bejson.com
// ==/UserScript==
// 解析到对象当中
    // 检测处理逻辑业务
const _check = function(state) {
    if (!state.author || state.author.length > 63) {
        return new Error("作者昵称应该在1-63个字之间.");
    }
    if (!/^[v|V]?[\d]{1,6}\.[\d]{1,6}/.test(state.version)) {
        return new Error("脚本版本号格式错误,例如:v1.0");
    }
    if (!/[a-z0-9\.\*\/]+/.test(state.match)) {
        return new Error("脚本匹配地址设置不正确.");
    }
    state.name = state.name.trim();
    if (!state.name || state.name.length < 3) {
        return new Error("脚本名称必须>3个字符");
    }
    return null;
};

export const JSAnnotation = function(script) {
    const state = {name:'-', 'version':'v1.0', icon:'-',
        author:'-', match:'-', script:script, description:'-'}
    
    let nStart = script.indexOf(scriptMarkStart);
    let nEnd = script.indexOf(scriptMarkEnd);
    if (nStart < 1 || nEnd < 1) {
        throw Error("代码注释丢失,无法保存.");
    }
    let annoStr = script.substring(nStart, nEnd);
    annoStr = annoStr.trim(); //过滤前后空格
    let aJsStr = annoStr.split("\n");
    for (let i = 0; i < aJsStr.length; i++) {
        let line = aJsStr[i].trim();
        if (!line) {//跳过逻辑
            continue;
        }
        if (line.startsWith("//")) {
            line = line.substring(2);
            line = line.trim();
        }
        line = line.replaceAll("\t", " ");
        let aStr = line.split(" ");
        if (!aStr || aStr.length < 2) { //跳过逻辑
            continue
        }
        let nameStr = aStr[0].trim().toLowerCase();
        let valueStr= aStr.slice(1).join(" ").trim();
        switch (nameStr) { //解析字段
            case "@name":
                state.name = valueStr;
                break;
            case "@version":
                state.version = valueStr;
                break;
            case "@description":
                state.description = valueStr;
                break;
            case "@author":
                state.author = valueStr;
                break;
            case "@match":
                state.match = valueStr;
                break;
            case "@icon":
                state.icon = valueStr;
                break;
        }
    }
    const errS = _check(state);
    if (errS != null) {
        throw errS
    }
    return state;
};
