text/csv;charset=utf-8' });\r\n        const url = URL.createObjectURL(blob);\r\n        const a = document.createElement('a');\r\n        a.href = url;\r\n        a.download = `评论数据_${Date.now()}.csv`;\r\n        a.click();\r\n        URL.revokeObjectURL(url);\r\n        Message.success(`已导出 ${count} 条评论`);\r\n    } catch (err) {\r\n        utilSrv.Write(utilSrv.INFO, \"评论导出失败\", err);\r\n        Message.error('导出失败，请稍后重试');\r\n    } finally {\r\n        dataStore.mPagesize = mPagesize;\r\n        await dataStore.load(1, link.value);\r\n        hideLoading();\r\n    }\r\n};\r\n\r\nonMounted(async ()=>{\r\n    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\r\n    if (tab && tab.url) {//地址\r\n       link.value = tab.url\r\n    }\r\n    await dataStore.load(1, link.value);\r\n})\r\n</script>\r\n<style scoped>\r\n.p-r-15 {\r\n    padding-right: 15px;\r\n}\r\n.wrap {\r\n    padding: 8px 0;\r\n    background-color: #aaa;\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center; \r\n    .search {\r\n        padding-left: 8px;\r\n    }\r\n    .actions{\r\n        padding-right: 8px;\r\n    }\r\n}\r\n.comment-cell {\r\n    padding: 2px 0;\r\n}\r\n.comment-head {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    margin-bottom: 5px;\r\n    flex-wrap: wrap;\r\n}\r\n.comment-count {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n    color: #667085;\r\n    font-size: 11px;\r\n}\r\n.comment-sub {\r\n    color: #98a2b3;\r\n    font-size: 11px;\r\n}\r\n.comment-filter {\r\n    padding: 1px 6px;\r\n    color: #b45309;\r\n    background: #fffbeb;\r\n    border-radius: 999px;\r\n    font-size: 10px;\r\n}\r\n.comment-empty {\r\n    padding: 8px 0;\r\n    color: #98a2b3;\r\n    font-size: 11px;\r\n}\r\n.comment-list {\r\n    position: relative;\r\n}\r\n.comment-list.is-collapsed {\r\n    padding-bottom: 10px;\r\n}\r\n.fade-mask {\r\n    position: absolute;\r\n    bottom: 0