<template>
  <div>
    <Button size="large" @click="doEditor" long type="success">
      <Icon type="ios-cog-outline" /> 模板配置
    </Button>
    <Modal v-model="mEditor" title="模板编辑器" :fullscreen="true">
      <div class="title">
        <label>名称</label>
        <Input v-model="mState.name" placeholder="请输入模板名称..."></Input>
      </div>
      <div class="title">
        <label>作者</label>
        <Input v-model="mState.author" placeholder="请输入模版作者..."></Input>
      </div>
      <div class="title">
        <label>站点</label>
        <Input v-model="mState.uri" placeholder="请输入适配站点地址..."></Input>
      </div>
      <div class="title">
        <label>简介</label>
        <Input v-model="mState.remark" placeholder="请输入模板简介..."></Input>
      </div>
      <div class="editor">
        <Codemirror 
          ref="editorRef"
          v-model="mState.fields" 
          :extensions="cmExtensions" 
          :style="{height: '100%'}"
          :indent-with-tab="true" 
          :tab-size="2" 
          placeholder="在此编写 YAML 模板…"
          />
      </div>
      <div v-if="mResult" class="result-c">
        <pre class="result">{{ mResult }}</pre>
      </div>
      <template #footer>
        <Space>
          <Button @click="mEditor=false">取消</Button>
          <Button type="warning" @click="doCompile">检测</Button>
          <Button type="success" @click="doSave2DB">保存</Button>
          <Button type="info" @click="doSave2Srv">上传</Button>
          <Button type="error" @click="doExec">直接执行</Button>
        </Space>
      </template>
    </Modal>
  </div>
</template>
<script setup>
import { computed, ref, reactive, watch } from 'vue';
import { Codemirror } from 'vue-codemirror';
import utilSrv from "@/static/js/base/utils";
import { basicSetup } from "codemirror"
import { yaml } from '@codemirror/lang-yaml';
import { oneDark } from '@codemirror/theme-one-dark';
import { Button, Icon, Modal,
  Space, Message } from 'view-ui-plus';
import { load } from 'js-yaml';
import { xIsLogin } from "@/static/js/base/request";
import { useStore } from '@/app/store/index';
import { useDevelopStore } from '@/app/store/develop';
import { updateTemplate } from "@/app/static/api.js";

const mStore = useStore();
const dStore = useDevelopStore();
const props = defineProps(['modelValue']);
const emit = defineEmits(['update:modelValue', 'change']);

const mEditor  = ref(false);
const mEditRow = ref(null);
const mResult  = ref('');
const SAMPLE_CODE = `- tag: title
  name: 标题
  xPath:
    - //h2[@class='subtitle']
  type: TEXT
- tag: date
  name: 日期
  xPath:
    - //div[contains(@class,'datetime')]
  type: TEXT
- tag: abstract
  name: 内容
  xPath:
    - //div[contains(@class,'abstract')]
  type: HTML`;

const mState = reactive({name:'', author:'', uri:'', remark:'', fields:SAMPLE_CODE});
const cmExtensions = computed(() => [basicSetup, yaml(), oneDark]);
watch(() => props.modelValue, (newVal) => {
  if (newVal !== mState.yaml) {
    mState.fields = newVal;
  }
});

const getCode = () => mState.fields;
const setCode = (newCode) => {
  mState.fields = newCode;
  emit('update:modelValue', newCode);
};

//打开编辑器
const doEditor = () => {
  mEditRow.value= null;
  mEditor.value = true;
};

//弹出编辑的情况
const setEditor = (row) => {
  mEditRow.value = row;
  setCode(row.meta.fields); 
  mState.uri = row.meta.uri;
  mState.name = row.meta.name;
  mState.remark = row.meta.remark;
  mState.author = row.meta.author;
  mEditor.value = true;
}

//前置条件
const mCondition = async() => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (tab && tab.url && tab.url.startsWith('http')) {
    return await mStore.openSetting(tab);
  }
  Message.error('开启环境设置异常');
  return false;
}

const YamlBabel = () => {
  const code = getCode();
  if (!code) {//执行代码的情况
    return '';
  }
  try {
    load(code);
    return code; // 无错误
  } catch (e) {
    Message.error(e.message);
    return '';
  }
}

const doCompile = async() => {
  const code = YamlBabel();
  if (code) {
    Message.success('模板校验正常');
  }
}

//保存数据资料信息
const doSave2DB = async() => {
  try {
    const es5Code = YamlBabel();
    if (!es5Code) {//执行代码的情况
      return
    }
    if (!mState.name || !mState.author || !mState.uri) {
      Message.error('模版数据不完整');
      return;
    }
    const data= {name:mState.name, author:mState.author,
      remark:mState.remark, uri:mState.uri, fields:es5Code};
    await dStore.putTemplate(data);
    Message.success('模板保存成功')
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "模板保存异常", errS);
    Message.error(errS.message);//失败的情况
  }
}

//保存数据到服务器
const doSave2Srv = async() => {
  try {
    const isLogin = await xIsLogin();
    if (!isLogin) {//已登录
      Message.error('请先登录才能上传云端');
      return
    }
    const es5Code = YamlBabel();
    if (!es5Code) {//执行代码的情况
      return
    }
    const meta = {name:mState.name, author:mState.author,
      remark:mState.remark, uri:mState.uri, fields:es5Code};
    if (mEditRow.value && mEditRow.value.id) {//编辑的情况
      meta.id = mEditRow.value.id;
    }
    const data = await updateTemplate(meta);
    if (!data) {//失败的情况
      return
    }
    meta.id = data.id; //更新记录逻辑
    await dStore.putTemplate(meta);
    mEditRow.value = meta; //更新数据库
    Message.success('模板上传成功');
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "模板上传异常", errS);
    Message.error(errS.message);//失败的情况
  }
}

//执行业务逻辑
const doExec = async() => {
  const isOk = await mCondition();
  if (!isOk) {//失败的情况逻辑
    return;
  }
  try {
    const es5Code = YamlBabel();
    if (!es5Code) {//执行代码的情况
      return
    }
    const params= { type: utilSrv.msgTypeWasmScraper, data:es5Code};
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    await chrome.tabs.sendMessage(tab.id, params, (response) => {
      mResult.value = JSON.stringify(response, null, 2);
    });
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "异步执行异常", errS);
    Message.error('刷新左边网页试试.');//失败的情况
  }
};

defineExpose({
  setEditor,
  getCode,
  setCode,
});
</script>
<style scoped>
.title {
  margin-bottom: 6px;
  display: flex; 
  align-items: 
  center; gap: 8px;
  label {
    width: 40px;
    flex-shrink: 0; 
    text-align: right;
  }
}

.editor {
  height: calc(100vh - 320px);
} 

.result {
  width: 100%;
  white-space: pre-wrap;      /* ✅ 保留空格和换行，同时允许自动换行 */
  word-wrap: break-word;      /* ✅ 长单词换行 */
  word-break: break-all;      /* ✅ 强制在任意字符处换行 */
  overflow-wrap: break-word;  /* ✅ 现代属性 */
  margin: 0;                  /* 去掉默认外边距 */
  box-sizing: border-box;
}
</style>