<template>
    <div class="template">
        <div class="wrap">
            <Button @click="refresh" type="text" size="small" icon="md-refresh">刷新</Button>
        </div>
        <Table stripe border :columns="columns" :data="dStore.template">
            <template #action="{ row }">
                <Button type="primary" size="small" style="margin-right: 5px" @click="edit(row)">编辑</Button>
                <Button type="error" size="small" @click="remove(row)">删除</Button>
            </template>
        </Table>
    </div>
</template>
<script setup>
import { onMounted } from 'vue';
import { Table, Button } from 'view-ui-plus';
import { useDevelopStore } from '@/app/store/develop';
import { deleteTemplate } from "@/app/static/api.js";

const emit = defineEmits(['edit']);
const dStore = useDevelopStore();
const columns = [
    {
        title: '模板名称',
        key: 'name',
        maxWidth: 240,
        minWidth: 100,
        resizable: true,
    },
    {
        title: '作者',
        maxWidth: 180,
        minWidth: 80,
        resizable: true,
        key: 'author'
    },
    {
        title: '描述',
        minWidth: 200,
        key: 'description',
        resizable: true,
    },
    {
        title: '更新时间',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        key: 'created_at'
    },
    {
        title: '操作',
        slot: 'action',
        maxWidth: 140,
        minWidth: 100,
        resizable: true,
        align: 'center'
    }
];

const edit = (row) => {
    emit('edit', row);
};

const remove = async (row) => {
    if (row.meta && row.meta.id) {
        const result = await deleteTemplate({id:row.meta.id});
        if (!result) {
            return;
        }
    }
    await dStore.deleteTemplate(row.skey);
};

const refresh = async() => {
    await dStore.loadTemplate();
};

onMounted(async ()=>{
    await dStore.loadTemplate();
})
</script>

<style scoped>
.wrap {
    padding: 8px;
    background-color: #aaa;
    display: flex;
    align-items: center;
    gap: 8px;
}
</style>