<template>
  <div class="tools-wrap">
    <section class="workspace-card toolbox-card">
      <div class="section-heading">
        <div>
          <h2>效率工具箱 
            <a :href="`${sUrl}/market.html`" title="查看更多" target="_blank">
              <Icon type="ios-code-working" size="17" />
            </a>
          </h2>
          <p>创意/截图/图片.视频下载/社媒内容提取/跨境电商采集将会都集中在这里...</p>
        </div>
        <Button type="text" size="small" @click="toolExpanded = !toolExpanded">
          {{ toolExpanded ? '收起' : `全部 ${tolStore.tolTotal} 项` }}
          <Icon :type="toolExpanded ? 'ios-arrow-up' : 'ios-arrow-down'" />
        </Button>
      </div>

      <div class="media-list">
        <div class="media-row">
          <div class="media-meta">
            <span class="media-icon image"><Icon type="md-images" size="20" /></span>
            <div>
              <strong>图片素材</strong>
              <span>在当前网页中选择并批量下载图片</span>
            </div>
          </div>
          <div class="media-actions">
            <Button size="small" type="primary" @click="doSelected('selected_image')">选中</Button>
            <Button size="small" @click="doSelected('selected_reset')">重置</Button>
            <Button size="small" type="success" @click="doSelected('download_image')">下载</Button>
          </div>
        </div>
        <div v-if="mStore.isManager" class="media-row">
          <div class="media-meta">
            <span class="media-icon video"><Icon type="ios-videocam" size="20" /></span>
            <div>
              <strong>视频素材</strong>
              <span>在当前网页中选择并批量下载视频</span>
            </div>
          </div>
          <div class="media-actions">
            <Button size="small" type="primary" @click="doSelected('selected_video')">选中</Button>
            <Button size="small" @click="doSelected('selected_reset')">重置</Button>
            <Button size="small" type="success" @click="doSelected('download_video')">下载</Button>
          </div>
        </div>
      </div>

      <div class="tool-grid">
        <article v-for="tool in visibleTools" :key="tool.sn" class="tool-card">
          <div class="tool-head">
            <div class="tool-cover" :class="`tone-${rColor(tool.id)}`">
              <img v-if="isLink(tool)" :src="utilSrv.getOssUrl(tool.cover)" />
              <Icon v-else :type="tool.cover" size="24" />
            </div>
            <div class="tool-head-copy">
              <strong class="tool-name">{{ tool.name }}</strong>
              <span class="tool-byline">{{ tool.author }} {{ tCategory(tool) }}</span>
            </div>
            <button type="button" class="tool-share" title="复制分享文案" @click.stop="shareTool(tool)">
              <Icon type="md-share" size="15" />
            </button>
          </div>
          <p class="tool-summary">{{ tool.summary }}</p>
          <!--div class="tool-tags">
            <span class="tool-tag"># {{ tool.category }}</span>
          </div-->
          <div class="tool-footer">
            <span class="tool-price" v-if="tool.installed && tool.installed === 1">{{ formatExp(tool) }}</span>
            <span class="tool-price" v-else>{{ formatPrice(tool) }}</span>
            <div class="tool-actions">
              <template v-if="isInstalled(tool)">
                <Button type="primary" size="small"
                  @click="exec(tool)">执行</Button>
              </template>
              <template v-else>
                <Button v-if="tool.is_retry !== 1" size="small" @click="trialTool(tool)">试用</Button>
                <Button type="primary" size="small" @click="buyTool(tool)">订购</Button>
              </template>
            </div>
          </div>
        </article>
      </div>
    </section>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import { useStore } from '@/app/store/index';
import { Button, Icon, Message } from 'view-ui-plus';
import utilSrv from "@/static/js/base/utils";
import { useToolsStore } from '@/app/store/tools';
import messageSrv from "@/static/js/base/m-sender";
import { doRetry, doBuy } from '@/app/static/api';
import { xIsLogin } from "@/static/js/base/request";
import { showLoading, hideLoading } from '@/app/static/loading';

const mStore = useStore();
const toolExpanded = ref(false);
const tolStore = useToolsStore();
const sUrl = process.env.S_URL;
const visibleTools = computed(() => toolExpanded.value ? tolStore.tools : tolStore.tools.slice(0, 3));
const tolCategory  = computed(()=>{
  return mStore.dict.category || [];
});
//工具是否是链接的情况判定
const isLink = (tool) => {
  if (tool && (tool.cover.startsWith('http') || tool.cover.startsWith('/upfile'))) {
    return true;
  }
  return false;
};

//记在工具的逻辑
const  loadMyTools = async() => {
  const params = {pageSize:100};
  await tolStore.loadTools(params);
}

onMounted(async()=>{
  await loadMyTools();
});

const rColor = (id) => {
  const c = ['blue', 'cyan', 'violet', 'pink', 'red'];
  return c[id%c.length];
};

const tCategory = (row) => {
  const item = tolCategory.value.find((item)=>item.value == row.category_id);
  return item? '#'+item.label:'';
};

const formatPrice = (tool) => {
  if(tool.price && tool.price > 0.1) {
    if (tool.days >= 999) {
      return `¥${tool.price}/永久`;
    }
    return `¥${tool.price}/${tool.days}天`;
  }
  return '免费';
};

const formatExp = (tool) => {
  const ss = (new Date()).getTime() / 1000;
  if (tool.expire < ss) {//已过期
    return '';
  }
  if (tool.expire < 0) {
    return '有效期@永久';
  }
  return '有效期@'+utilSrv.DateStr(tool.expire*1000,
   'y-m-d H:i:s');
};

const isInstalled = (tool) => {
  if (tool.price < 0.1 || (tool.installed && tool.installed === 1)) {
    return true;//免费|获取订购情况
  }
  return false;
};

//验证域名的情况
const cDomain = async (tool) => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (!tab || !tab.url || !tab.url.startsWith('http')) {
    Message.error('当前tab非HTTP协议无法执行');
    return null;
  }
  if (tool.domain != '*' && !tab.url.includes(tool.domain)) {
    Message.error('当前tab地址与任务不匹配,无法执行');
    return null;
  }
  return tab;
}

//执行任务的业务处理逻辑
const exec = async (tool) => {
  try {
    const tab = await cDomain(tool);
    if (!tab) {//验证不通过
      return;
    }
    const isOk = await mStore.openSetting(tab);
    if (isOk && tool) {//消息链路已经打开的情况
      showLoading("任务执行中...");
      await tolStore.runXTool(tab, tool);
    }
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "异步执行异常", errS);
    Message.error(errS.message);
  } finally {//总是会自动执行
    setTimeout(()=>{
      hideLoading();
    }, 1500);
  }
};

//试用的业务处理逻辑
const trialTool = async (tool) => {
  try {
    const isLogin= await xIsLogin();
    if (!isLogin) {//未登录的情况
      Message.error('请先登录再申请试用');
      return;
    }
    const tab = await cDomain(tool);
    if (!tab) {//验证不通过
      return;
    }
    const isOk = await mStore.openSetting(tab);
    if (!isOk) {//消息链路已经打开的情况
      return;
    }
    showLoading("试用申请中...");
    const result = await doRetry({uuid:tool.sn});
    if (result) {//执行成功
      tool.is_retry = 1;
      await tolStore.runXTool(tab, tool);
    }
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "异步执行异常", errS);
    Message.error(errS.message);
  } finally {//总是会自动执行
    setTimeout(()=>{
      hideLoading();
    }, 500);
  }
};

//购买下单的逻辑
const buyTool = async (tool) => {
  try {
    const isLogin= await xIsLogin();
    if (!isLogin) {//未登录的情况
      Message.error('请先登录再申请试用');
      return;
    }
    showLoading("订购下单中...");
    const params = {id: parseInt(tool.id),
      name: tool.name, price: parseFloat(tool.price)};
    const result = await doBuy(params);
    if (result && result.pay_url) {//打开去支付
      window.open(result.pay_url, '_blank');
    }
  } catch(errS) {
    utilSrv.Write(utilSrv.INFO, "异步执行异常", errS);
    Message.error(errS.message);
  } finally {//总是会自动执行
    setTimeout(()=>{
      hideLoading();
    }, 500);
  }
};

//写入剪贴板，优先 Clipboard API，失败降级 execCommand
const writeClipboard = async (text) => {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (err) {
    utilSrv.Write(utilSrv.INFO, "剪贴板不可用", err);
  }
  try {
    const area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', 'readonly');
    area.style.position = 'fixed';
    area.style.top = '-1000px';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(area);
    return ok;
  } catch (err) {
    utilSrv.Write(utilSrv.INFO, "复制失败", err);
    return false;
  }
};

//分享落地页，优先使用服务端下发的地址
const shareLink = async (tool) => {
  const isOk = await xIsLogin();
  if (isOk && mStore.user && mStore.user.userId > 0) {
    return `${sUrl}/tool/${mStore.user.userId}-${tool.sn}.html`;
  }
  return `${sUrl}/tool/${tool.sn}.html`;
};

//组装简洁版分享文案（朋友圈/小红书可直接粘贴）
const buildShareText = async (tool) => {
  const summary = (tool.summary || '').trim();
  const cat = tCategory(tool).replace('#', '');
  const price = (tool.price && tool.price > 0.1) ? `¥${tool.price}/${tool.days}天` : '免费';
  const tags = ['#浏览器插件'];
  if (cat) {
    tags.push('#' + cat);
  }
  const link = await shareLink(tool);
  const title = summary ? `${tool.name}｜${summary}` : tool.name;
  const lines = [title, '', `${price} 装上就能用 👇`, link, '', tags.join(' ')];
  return lines.join('\n');
};

//点击分享图标：把文案和链接复制到剪贴板
const shareTool = async (tool) => {
  const text = await buildShareText(tool);
  const ok = await writeClipboard(text);
  if (ok) {
    Message.success('分享文案已复制，分享给朋友吧!');
  } else {
    Message.error('复制失败，请手动复制');
  }
};

//修改配置
const doMessageConfig = async()=>{
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (tab && tab.url && tab.url.startsWith('http')) {
    mStore.setting.site_message = true; //开启网络
    await mStore.svSetting(tab, false);
  }
};

const doSelected = async (opType='video') => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (!tab) {
    Message.error('未找到活动标签页');
    return;
  }

  const params = { type: utilSrv.msgTypeSelectedImages };
  if (opType == 'selected_video') {
    params.type = utilSrv.msgTypeSelectedVideos;
  } else if (opType == 'selected_reset') {
    params.type = utilSrv.msgTypeSelectedClear;
  } else if (opType == 'download_image') {
    params.type = utilSrv.msgTypeDownloadImages;
  } else if (opType == 'download_video') {
    params.type = utilSrv.msgTypeDownloadVideos;
    params.link = tab.url;
    params.title = tab.title;
    const response = await messageSrv.doSendMessage(params);
    if (response && response.code === 0) {
      Message.success('操作完成');
    } else {
      Message.error('操作失败,刷新重新操作');
      utilSrv.Write(utilSrv.INFO, "操作失败", response);
    }
    return;
  }
  if (!mStore.setting.site_message) {
    await doMessageConfig();//重置 需要休眠一下
    return;
  }
  const response = await messageSrv.doTabSendMessage(tab.id, params);
  if (response && response.code === 0) {
    Message.success('操作完成');
  } else {
    Message.error('操作失败,刷新重新操作');
    utilSrv.Write(utilSrv.INFO, "操作失败", response);
  }
};
</script>
<style scoped>
