ze=\"large\" @click=\"doIgnore\">稍后再说</Button>\n                <Button v-else long size=\"large\" :loading=\"isChecking\" @click=\"reCheck\">重新检测</Button>\n            </div>\n        </div>\n    </Modal>\n</template>\n<script setup>\nimport { ref, reactive, watch, onMounted, computed } from 'vue';\nimport { Button, Icon, Modal, Message } from 'view-ui-plus';\nimport { useStore } from '@/app/store/index';\n\nconst mStore = useStore();\nconst mVersion  = ref(false);\nconst isChecking= ref(false);\n//状态数据资料信息\nconst curState = reactive({\n    ignoreVer:'',\n    hasUpdate:false,\n    current: process.env.APP_VERSION,\n    currentCode: process.env.APP_VERCODE,\n});\n\n//版本变动的情况\nwatch(() => mStore.version, ()=>{\n    init();\n});\n\n//最新的版本\nconst latest = computed(()=>{\n    if (!mStore.version) {\n        return '';\n    }\n    return mStore.version.name;\n});\n\n//初始化业务逻辑\nconst init = async() => {\n    try {\n        const manifest = chrome.runtime.getManifest();\n        if (manifest && manifest?.version) {\n            curState.current = manifest?.version;\n        }\n    } catch(err) {\n        //\n    }\n    const data = await chrome.storage.local.get('ignoreVersion');\n    curState.ignoreVer = data?.ignoreVersion || '';\n    if (mStore.version && mStore.version.ver \n            && mStore.version.ver > curState.currentCode \n            && curState.ignoreVer != latest.value) {\n        curState.hasUpdate = true; //有新版本需要更新的情况\n    }\n}\n//当前的版本数据资料信息\nonMounted(async()=>{\n    init(); //初始化业务逻辑\n});\n\n//打开版本详情弹窗\nconst openVersion = async() => {\n    mVersion.value = true;\n};\n\n//重新检测版本\nconst reCheck = async() => {\n    isChecking.value = true;\n    await mStore.loadDict();\n    isChecking.value = false;\n    const isNew = mStore.version && mStore.version.ver > curState.currentCode;\n    Message.success(isNew ? '发现新版本' : '当前已是最新版本');\n    curState.hasUpdate = isNew; //重新展示升级\n    await chrome.storage.local.remove('ignoreVersion');\n};\n\n//跳转到下载地址\nconst doDownload = async() => {\n    let link = mStore.version.url;\n    if (!link) {//降级使用插件主页地址\n        try {\n            link = chrome.runtime.getManifest().homepage_url || '';\n        } catch(err) {\n            link = '';\n        }\n    }\n    if (!link) {\n        Message.info('暂未配置下载地址');\n        return;\n    }\n    await chrome.tabs.create({url: link});\n};\n\n//忽略本次版本提示\nconst doIgnore = async() => {\n    curState.ignoreVer = latest.value;\n    curState.hasUpdate = false;\n    const sData = {ignoreVersion:curState.ignoreVer};\n    await chrome.storage.local.set(sData);\n    mVersion.value = false;\n    Message.success('已忽略该版本提示');\n};\n\n</script>\n<style scoped>\n.version-entry {\n    display: inline-flex;\n    align-items: center;\n    flex: none;\n    gap: 3px;\n    padding: 2px 7px;\n    color: rgba(255, 255, 255, 0.86);\n    background: rgba(255, 255, 255, 0.18);\n    border: 1px solid rgba(255, 255, 255, 0.24);\n    border-radius: 999px;\n    font-size: 11px;\n    line-height: 16px;\n    cursor: pointer;\n    transition: background 0.2s ease, color 0.2s ease;\n}\n.version-entry:hover {\n    color: #ffffff;\n    background: rgba(255, 255, 255, 0.3);\n}\n.version-entry.has-update {\n    color: #7c2d12;\n    background: #fbbf24;\n    border-color: #fcd34d;\n}\n.version-entry.has-update:hover {\n    background: #f59e0b;\n}\n.version-text {\n    max-width: 110px;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n.update-dot {\n    width: 5px;\n    height: 5px;\n    background: #dc2626;\n    border-radius: 50%;\n    box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.25);\n}\n.version-modal {\n    padding: 4px 2px 2px;\n}\n.version-banner {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 12px;\n    background: #f0fdf4;\n    border: 1px solid #bbf7d0;\n    border-radius: 12px;\n}\n.version-banner.is-new {\n    background: #fffbeb;\n    border-color: #fde68a;\n}\n.banner-icon {\n    display: grid;\n    width: 3