`, "",{"version":3,"sources":["webpack://./src/app/popup/index/components/editor-js.vue"],"names":[],"mappings":";AAmPA;EACE,2BAA2B;AAC7B","sourcesContent":["<template>\r\n  <div>\r\n    <Button size=\"large\" @click=\"doEditor\" long type=\"primary\">\r\n      <Icon type=\"ios-cog\" /> 脚本开发\r\n    </Button>\r\n    <Modal v-model=\"mEditor\" title=\"代码编辑器\" :fullscreen=\"true\">\r\n      <div class=\"editor\">\r\n        <Codemirror \r\n          ref=\"editorRef\"\r\n          v-model=\"code\" \r\n          :extensions=\"cmExtensions\" \r\n          :style=\"{height: '100%'}\"\r\n          :indent-with-tab=\"true\" \r\n          :tab-size=\"2\" \r\n          placeholder=\"在此编写 JS 代码…\"\r\n          />\r\n      </div>\r\n      <template #footer>\r\n        <Space>\r\n          <Button @click=\"mEditor=false\">取消</Button>\r\n          <Button type=\"warning\" @click=\"doCompile\">编译</Button>\r\n          <Button type=\"success\" @click=\"doSave2DB\">保存</Button>\r\n          <Button type=\"info\" @click=\"doSave2Srv\">上传</Button>\r\n          <Button type=\"error\" @click=\"doExec\">直接执行</Button>\r\n          <Button type=\"primary\" @click=\"reExec\">刷新执行</Button>\r\n        </Space>\r\n      </template>\r\n    </Modal>\r\n  </div>\r\n</template>\r\n<script setup>\r\nimport { computed, ref, watch } from 'vue';\r\nimport { Codemirror } from 'vue-codemirror';\r\nimport utilSrv from \"@/static/js/base/utils\";\r\nimport { javascript } from '@codemirror/lang-javascript';\r\nimport { oneDark } from '@codemirror/theme-one-dark';\r\nimport { Button, Icon, Modal,\r\n  Space, Message } from 'view-ui-plus';\r\nimport { xIsLogin } from \"@/static/js/base/request\";\r\nimport { JSAnnotation } from '@/app/static/annotation';\r\nimport { useStore } from '@/app/store/index';\r\nimport { useDevelopStore } from '@/app/store/develop';\r\nimport { updateScript } from \"@/app/static/api.js\";\r\n\r\nconst mStore = useStore();\r\nconst dStore = useDevelopStore();\r\nconst props = defineProps(['modelValue']);\r\nconst emit = defineEmits(['update:modelValue', 'change']);\r\n\r\nconst mEditor   = ref(false);\r\nconst mEditRow= ref(null);\r\nconst SAMPLE_CODE = `// ==UserScript==\r\n// @name         案例脚本名称\r\n// @version      v1.0\r\n// @description  这里填写脚本的描述数据资料信息\r\n// @author       X-scraper\r\n// @match        https://*.*/\r\n// @icon         https://admin.x-scraper.cc/favicon.ico\r\n// ==/UserScript==\r\n(function(){\r\n    // --- 浏览器一打开就执行 ---\r\n    xScraper.hookSrv.RegisterStart(function(){\r\n        xScraper.utilSrv.Write(xScraper.utilSrv.INFO, \"开启启动执行脚本...\");\r\n        // --- 网络拦截用于获取数据 ---\r\n        xScraper.hookSrv.RegisterNetSniffer(\"*\", function(task, data, url){\r\n            xScraper.utilSrv.Write(xScraper.utilSrv.INFO,\r\n                 \"监听网络\", task, data, url);\r\n        });\r\n    });\r\n    // --- dom页面准备继续的执行代码 ---\r\n    xScraper.hookSrv.RegisterDomLoaded(function(){\r\n        xScraper.utilSrv.Write(xScraper.utilSrv.INFO, \"网页dom加载完成执行...\");\r\n    });\r\n})();`;\r\n\r\nconst code = ref(props.modelValue || SAMPLE_CODE);\r\nconst cmExtensions = computed(() => [javascript(), oneDark]);\r\nwatch(() => props.modelValue, (newVal) => {\r\n  if (newVal !== code.value) {\r\n    code.value = newVal;\r\n  }\r\n});\r\n\r\nconst getCode = () => code.value;\r\nconst setCode = (newCode) => {\r\n  code.value = newCode;\r\n  emit('update:modelValue', newCode);\r\n};\r\n\r\n//打开编辑器\r\nconst doEditor = () => {\r\n  mEditRow.value= null;\r\n  mEditor.value = true;\r\n};\r\n\r\n//弹出编辑的情况\r\nconst setEditor = (row) => {\r\n  mEditRow.value = row;\r\n  setCode(row.meta.script); \r\n  mEditor.value = true;\r\n}\r\n\r\n//前置条件\r\nconst mCondition = async() => {\r\n  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\r\n  if (tab && tab.url && tab.url.startsWith('http')) {\r\n    return await mStore.openSetting(tab);\r\n  }\r\n  Message.error('开启环境设置异常');\r\n  return false;\r\n}\r\n\r\nconst JsBabel = () => {\r\n  const code = getCode();\r\n  if (!code) {//执行代码的情况\r\n    return '';\r\n  }\r\n  const result = Babel.transform(code, {\r\n    presets: [\r\n      ['env', {\r\n        targets: { ie: '11' }, \r\n        modules: false,\r\n      }]\r\n    ]\r\n  });\r\n  const es5Code = result.code;\r\n  return es5Code;\r\n}\r\n\r\nconst doCompile = async() => {\r\n  try {\r\n    const es5Code = JsBabel();\r\n    if (!es5Code) {//执行代码的情况\r\n      Message.error('请编写要执行的代码');\r\n      return\r\n    }\r\n    setCode(es5Code); //设置转义编码\r\n    utilSrv.Write(utilSrv.INFO, \"转换后的 ES5 代码:\", es5Code);\r\n    Message.success('代码转义成功')\r\n  } catch(err) {\r\n    utilSrv.Write(utilSrv.INFO, \"异步执行异常\", err);\r\n    Message.error('编译脚本执行异常.');//失败的情况\r\n  }\r\n}\r\n\r\n//保存数据资料信息\r\nconst doSave2DB = async() => {\r\n  try {\r\n    const es5Code = JsBabel();\r\n    if (!es5Code) {//执行代码的情况\r\n      Message.error('请编写要执行的代码');\r\n      return\r\n    }\r\n    const meta = JSAnnotation(es5Code);\r\n    await dStore.putScript(meta);\r\n    Message.success('代码保存成功')\r\n  } catch(errS) {\r\n    utilSrv.Write(utilSrv.INFO, \"代码保存异常\", errS);\r\n    Message.error(errS.message);//失败的情况\r\n  }\r\n}\r\n\r\n//保存数据到服务器\r\nconst doSave2Srv = async() => {\r\n  try {\r\n    const isLogin = await xIsLogin();\r\n    if (!isLogin) {//已登录\r\n      Message.error('请先登录才能上传云端');\r\n      return\r\n    }\r\n    const es5Code = JsBabel();\r\n    if (!es5Code) {//执行代码的情况\r\n      Message.error('请编写要执行的代码');\r\n      return\r\n    }\r\n    const meta = {script:es5Code, version_code:1};\r\n    if (mEditRow.value && mEditRow.value.id) {//编辑的情况\r\n      meta.id = mEditRow.value.id;\r\n      meta.price = mEditRow.value.price || 0;\r\n      meta.isprivacy = mEditRow.value.isprivacy || 1;\r\n      meta.version_code = mEditRow.value.version_code || 1;\r\n    }\r\n    const data = await updateScript(meta);\r\n    if (!data) {//失败的情况\r\n      return\r\n    }\r\n    const sMeta = JSAnnotation(es5Code);\r\n    sMeta.id = data.id; //更新记录逻辑\r\n    await dStore.putScript(sMeta);\r\n    mEditRow.value = sMeta; //更新数据库\r\n    Message.success('代码上传成功');\r\n  } catch(errS) {\r\n    utilSrv.Write(utilSrv.INFO, \"代码上传异常\", errS);\r\n    Message.error(errS.message);//失败的情况\r\n  }\r\n}\r\n\r\nconst doExec = async() => {\r\n  const isOk = await mCondition();\r\n  if (!isOk) {//失败的情况\r\n    return;\r\n  }\r\n  try {\r\n    const es5Code = JsBabel();\r\n    if (!es5Code) {//执行代码的情况\r\n      Message.error('请编写要执行的代码');\r\n      return\r\n    }\r\n    const params= { type: utilSrv.msgTypeRunScript, script: es5Code, run_ctx: 'content_script' };\r\n    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });\r\n    await chrome.tabs.sendMessage(tab.id, params);\r\n  } catch(errS) {\r\n    utilSrv.Write(utilSrv.INFO, \"异步执行异常\", errS);\r\n    Message.error('刷新左边网页试试.');//失败的情况\r\n  }\r\n};\r\n\r\n//刷新执行\r\nconst reExec = async() => {\r\n  const isOk = await mCondition();\r\n  if (!isOk) {//失败的情况\r\n    return;\r\n  }\r\n  try {\r\n    const es5Code = JsBabel();\r\n    if (!es5Code) {//执行代码的情况\r\n      Message.error('请编写要执行的代码');\r\n      return\r\n    }\r\n    await dStore.runScript(es5Code, null);\r\n  } catch(errS) {\r\n    utilSrv.Write(utilSrv.INFO, \"异步执行异常\", errS);\r\n    Message.error(errS.message);//失败的情况\r\n  }\r\n}\r\n\r\ndefineExpose({\r\n  setEditor,\r\n  getCode,\r\n  setCode,\r\n});\r\n</script>\r\n<style scoped>\r\n.editor {\r\n  height: calc(100vh - 200px);\r\n} \r\n</style>"],"sourceRoot":""}]);
